import { MotiView } from 'moti'
import {
	ExpoSpeechRecognitionModule,
	useSpeechRecognitionEvent,
	ExpoSpeechRecognitionResultEvent
} from 'expo-speech-recognition'
import { useEffect, useRef, useState } from 'react'
import { TranscriptView } from './TranscriptView'
import { SpeechToTextActions } from './SpeechToTextActions'
import { defineStyles } from '@/utils/defineStyles'
import { LoopingAnimation } from './LoopingAnimation'
import { LiquidGlassView } from '@/components'
import { useSpeechPermissionStore } from '@/stores'

type SpeechToTextViewProps = {
	isSpeaking: boolean
	setIsSpeaking: (isSpeaking: boolean) => void
	prompt: string
	setPrompt: (prompt: string) => void
	withLiquidGlass: boolean
	onAfterSubmit?: () => void
}

export const SpeechToTextView = ({
	isSpeaking,
	setIsSpeaking,
	prompt,
	setPrompt,
	withLiquidGlass,
	onAfterSubmit
}: SpeechToTextViewProps) => {
	const [recognizing, setRecognizing] = useState(true) // true on mount always
	const [isTransferred, setIsTransferred] = useState(false)
	const pauseRequested = useRef(false)

	const committedRef = useRef('')
	const segmentRef = useRef('')

	const isNewSegmentRef = useRef(false)

	const commitSegment = () => {
		if (!segmentRef.current) return
		committedRef.current = committedRef.current + ' ' + segmentRef.current
		segmentRef.current = ''
		setPrompt(committedRef.current)
	}

	const getTranscript = (
		event: ExpoSpeechRecognitionResultEvent
	): { text: string; isFinal: boolean } => {
		let text = ''
		let isFinal = false
		if (event.results.length) {
			const last = event.results[event.results.length - 1]
			if (last && 'transcript' in last && typeof last.transcript === 'string') {
				text = last.transcript
			}
			isFinal = !!event.isFinal
		}
		return { text, isFinal }
	}

	useSpeechRecognitionEvent('start', () => {
		setRecognizing(true)
		segmentRef.current = ''
		isNewSegmentRef.current = true
		setPrompt(committedRef.current)
	})

	useSpeechRecognitionEvent('end', () => {
		commitSegment()
		setRecognizing(false)
		if (pauseRequested.current) {
			pauseRequested.current = false
		}
	})

	useSpeechRecognitionEvent(
		'result',
		(event: ExpoSpeechRecognitionResultEvent) => {
			const { text, isFinal } = getTranscript(event)

			segmentRef.current = text || ''
			setPrompt(committedRef.current + ' ' + segmentRef.current)

			if (isNewSegmentRef.current) {
				isNewSegmentRef.current = false
			}

			if (isFinal) {
				commitSegment()
			}
		}
	)

	useSpeechRecognitionEvent('error', (event) => {
		if (pauseRequested.current && event.error === 'aborted') return
	})

	const handleStart = async () => {
		const result = await ExpoSpeechRecognitionModule.requestPermissionsAsync()
		if (!result.granted) {
			setIsSpeaking(false)
			useSpeechPermissionStore.getState().setHasSpeechPermission(false)
			return
		}
		ExpoSpeechRecognitionModule.start({
			lang: 'en-US',
			interimResults: true,
			continuous: true,
			addsPunctuation: true
		})
	}

	const handlePause = () => {
		pauseRequested.current = true
		ExpoSpeechRecognitionModule.abort()
	}

	const handleStop = () => {
		ExpoSpeechRecognitionModule.stop()
	}

	const handleReset = () => {
		handleStop()
		pauseRequested.current = false
		setIsSpeaking(false)
		committedRef.current = ''
		segmentRef.current = ''
		setPrompt('')
	}

	const handleSubmit = async () => {
		handleStop()
		setIsTransferred(true)
		setIsSpeaking(false)
		if (onAfterSubmit) {
			onAfterSubmit()
		}
	}

	// only call once on mount and reset on unmount
	useEffect(() => {
		handleStart()
	}, [])

	return (
		<MotiView
			from={{ opacity: 0 }}
			animate={{ opacity: isSpeaking ? 1 : 0 }}
			exit={{ opacity: isSpeaking ? 0 : 1 }}
			transition={{
				duration: 300,
				type: 'timing',
				delay: 100
			}}
			exitTransition={{
				duration: 300,
				type: 'timing',
				delay: 0
			}}
			style={styles.speakingOverlay}
		>
			<LiquidGlassView
				disabled={!withLiquidGlass}
				style={{
					flex: 1,
					justifyContent: 'flex-end',
					paddingHorizontal: 40,
					paddingBottom: 32
				}}
			>
				<TranscriptView
					prompt={prompt}
					isTransferred={isTransferred}
					withGradient={!withLiquidGlass}
				/>
				{isTransferred && <LoopingAnimation />}
				<SpeechToTextActions
					recognizing={recognizing}
					isNotEmpty={!!prompt}
					isTransferred={isTransferred}
					handlePause={handlePause}
					handleStart={handleStart}
					handleReset={handleReset}
					handleSubmit={handleSubmit}
				/>
			</LiquidGlassView>
		</MotiView>
	)
}

const styles = defineStyles({
	speakingOverlay: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0
	}
})
